describe('User Login - Authentication', () => {
  const validEmail = 'testuser@example.com';
  const validPassword = 'SecurePassword123!';
  const invalidEmail = 'invalid@example.com';
  const invalidPassword = 'WrongPassword123!';
  const loginUrl = 'http://localhost:3000/login';
  const dashboardUrl = 'http://localhost:3000/dashboard';

  beforeEach(() => {
    cy.visit(loginUrl);
    cy.clearCookies();
    cy.clearLocalStorage();
  });

  it('should successfully log in with valid credentials and redirect to dashboard', () => {
    // Verify login page elements are visible
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="login-button"]').should('be.visible');

    // Enter valid credentials
    cy.get('[data-testid="email-input"]').type(validEmail, { delay: 50 });
    cy.get('[data-testid="password-input"]').type(validPassword, { delay: 50 });

    // Submit login form
    cy.get('[data-testid="login-button"]').click();

    // Verify successful login
    cy.url().should('include', dashboardUrl);
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
    cy.get('[data-testid="user-profile-name"]').should('contain', 'Test User');

    // Verify session token is stored
    cy.window().then((win) => {
      expect(win.localStorage.getItem('authToken')).to.exist;
    });
  });

  it('should display error message when logging in with invalid credentials', () => {
    // Enter invalid credentials
    cy.get('[data-testid="email-input"]').type(invalidEmail, { delay: 50 });
    cy.get('[data-testid="password-input"]').type(invalidPassword, { delay: 50 });

    // Submit login form
    cy.get('[data-testid="login-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid email or password');

    // Verify user remains on login page
    cy.url().should('include', loginUrl);
    cy.url().should('not.include', dashboardUrl);

    // Verify no auth token is stored
    cy.window().then((win) => {
      expect(win.localStorage.getItem('authToken')).to.be.null;
    });
  });

  it('should display validation error when email field is empty', () => {
    // Leave email empty and enter password
    cy.get('[data-testid="password-input"]').type(validPassword, { delay: 50 });

    // Submit login form
    cy.get('[data-testid="login-button"]').click();

    // Verify validation error
    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('[data-testid="email-error"]').should('contain', 'Email is required');

    // Verify user remains on login page
    cy.url().should('include', loginUrl);
  });

  it('should display validation error when password field is empty', () => {
    // Enter email but leave password empty
    cy.get('[data-testid="email-input"]').type(validEmail, { delay: 50 });

    // Submit login form
    cy.get('[data-testid="login-button"]').click();

    // Verify validation error
    cy.get('[data-testid="password-error"]').should('be.visible');
    cy.get('[data-testid="password-error"]').should('contain', 'Password is required');

    // Verify user remains on login page
    cy.url().should('include', loginUrl);
  });

  it('should handle network error gracefully during login attempt', () => {
    // Intercept and fail the login API request
    cy.intercept('POST', '**/api/auth/login', { forceNetworkError: true }).as('loginRequest');

    // Enter valid credentials
    cy.get('[data-testid="email-input"]').type(validEmail, { delay: 50 });
    cy.get('[data-testid="password-input"]').type(validPassword, { delay: 50 });

    // Submit login form
    cy.get('[data-testid="login-button"]').click();

    // Wait for failed request
    cy.wait('@loginRequest');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Network error');

    // Verify user remains on login page
    cy.url().should('include', loginUrl);
  });

  it('should disable login button while request is in progress', () => {
    // Intercept login request and delay response
    cy.intercept('POST', '**/api/auth/login', (req) => {
      req.reply((res) => {
        res.delay(2000);
      });
    }).as('loginRequest');

    // Enter valid credentials
    cy.get('[data-testid="email-input"]').type(validEmail, { delay: 50 });
    cy.get('[data-testid="password-input"]').type(validPassword, { delay: 50 });

    // Submit login form
    cy.get('[data-testid="login-button"]').click();

    // Verify button is disabled during request
    cy.get('[data-testid="login-button"]').should('be.disabled');
    cy.get('[data-testid="login-button"]').should('contain', 'Logging in...');

    // Wait for request to complete
    cy.wait('@loginRequest');

    // Verify button is re-enabled after request
    cy.get('[data-testid="login-button"]').should('not.be.disabled');
  });

  it('should clear error messages when user modifies input fields', () => {
    // Enter invalid credentials and submit
    cy.get('[data-testid="email-input"]').type(invalidEmail, { delay: 50 });
    cy.get('[data-testid="password-input"]').type(invalidPassword, { delay: 50 });
    cy.get('[data-testid="login-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Clear email field and type new value
    cy.get('[data-testid="email-input"]').clear();
    cy.get('[data-testid="email-input"]').type(validEmail, { delay: 50 });

    // Verify error message is cleared
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
